/// Static bilingual library content: stories + grammar lessons + vocabulary.
/// All English text lives in [BookPage.en] (rendered LTR via `En`),
/// all Persian text in [BookPage.fa] (rendered RTL via the theme).
class BookPage {
  const BookPage(this.en, this.fa);

  final String en;
  final String fa;
}

class BookMeta {
  const BookMeta({
    required this.id,
    required this.titleFa,
    required this.titleEn,
    required this.emoji,
    required this.pages,
    this.level = 'A1',
    this.cover,
    this.authorEn,
  });

  final String id;
  final String titleFa;
  final String titleEn;
  final String emoji;
  final List<BookPage> pages;

  /// CEFR level used for grouping and filtering: A1, A2, B1, B2, C1.
  final String level;

  /// Optional cover image asset path (assets/covers/...).
  final String? cover;

  /// Optional author line shown on the cover.
  final String? authorEn;
}

